SELECT "customerid", "taxid", "status", "lastname", "firstname", "middleinitial", "gender", "tier", "dob", "addressline1", "addressline2", "postalcode", "city", "stateprov", "country", "phone1", "phone2", "phone3", "email1", "email2", "nationaltaxratedesc", "nationaltaxrate", "localtaxratedesc", "localtaxrate", "agencyid", "creditrating", "networth", "marketingnameplate", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY customerid, effectivedate) AS INT) AS "sk_customerid" FROM (SELECT TRY_CAST((CAST(c.C_ID AS INT)) AS INT) AS "customerid", TRY_CAST((CAST(COALESCE(c.C_TAX_ID, '') AS TEXT)) AS TEXT) AS "taxid", TRY_CAST((act.ActionType) AS TEXT) AS "status", TRY_CAST((CAST(COALESCE(n.C_L_NAME, '') AS TEXT)) AS TEXT) AS "lastname", TRY_CAST((CAST(n.C_F_NAME AS TEXT)) AS TEXT) AS "firstname", TRY_CAST((CAST(n.C_M_NAME AS TEXT)) AS TEXT) AS "middleinitial", TRY_CAST((c.C_GNDR) AS TEXT) AS "gender", TRY_CAST((TRY_CAST(c.C_TIER AS INT)) AS INT) AS "tier", TRY_CAST((COALESCE(c.C_DOB, CAST('1900-01-01' AS DATE))) AS DATE) AS "dob", TRY_CAST((CAST(COALESCE(a.C_ADLINE1, '') AS TEXT)) AS TEXT) AS "addressline1", TRY_CAST((CAST(a.C_ADLINE2 AS TEXT)) AS TEXT) AS "addressline2", TRY_CAST((CAST(COALESCE(a.C_ZIPCODE, '') AS TEXT)) AS TEXT) AS "postalcode", TRY_CAST((CAST(COALESCE(a.C_CITY, '') AS TEXT)) AS TEXT) AS "city", TRY_CAST((CAST(COALESCE(a.C_STATE_PROV, '') AS TEXT)) AS TEXT) AS "stateprov", TRY_CAST((a.C_CTRY) AS TEXT) AS "country", TRY_CAST((CAST(SUBSTRING(p1.C_CTRY_CODE || p1.C_AREA_CODE || p1.C_LOCAL || p1.C_EXT, 1, 30) AS TEXT)) AS TEXT) AS "phone1", TRY_CAST((LEFT(CONCAT(p2.C_CTRY_CODE, p2.C_AREA_CODE, p2.C_LOCAL, p2.C_EXT), 30)) AS TEXT) AS "phone2", TRY_CAST((LEFT(CASE WHEN NOT p3.C_LOCAL IS NULL THEN CONCAT(CASE WHEN NOT p3.C_CTRY_CODE IS NULL THEN p3.C_CTRY_CODE || '-' END, CASE WHEN NOT p3.C_AREA_CODE IS NULL THEN p3.C_AREA_CODE || '-' END, p3.C_LOCAL, CASE WHEN NOT p3.C_EXT IS NULL THEN ' ext ' || p3.C_EXT END) END, 30)) AS TEXT) AS "phone3", TRY_CAST((CAST(ci.C_PRIM_EMAIL AS TEXT)) AS TEXT) AS "email1", TRY_CAST((CAST(ci.C_ALT_EMAIL AS TEXT)) AS TEXT) AS "email2", TRY_CAST((tr_nat.TX_NAME) AS TEXT) AS "nationaltaxratedesc", TRY_CAST((tr_nat.TX_RATE) AS DECIMAL(6, 5)) AS "nationaltaxrate", TRY_CAST((tr_loc.TX_NAME) AS TEXT) AS "localtaxratedesc", TRY_CAST((tr_loc.TX_RATE) AS DECIMAL(6, 5)) AS "localtaxrate", TRY_CAST((CAST(NULL AS TEXT)) AS TEXT) AS "agencyid", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "creditrating", TRY_CAST((CAST(NULL AS DECIMAL(10))) AS DECIMAL(10)) AS "networth", TRY_CAST((CAST(NULL AS TEXT)) AS TEXT) AS "marketingnameplate", TRY_CAST((COALESCE(act.ActionType = 'NEW', FALSE)) AS BOOLEAN) AS "iscurrent", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "batchid", TRY_CAST((CAST(TRY_CAST(REPLACE(REPLACE(act.ActionTS, 'T', ' '), 't', ' ') AS TIMESTAMP) AS DATE)) AS DATE) AS "effectivedate", TRY_CAST((CAST('9999-12-31' AS DATE)) AS DATE) AS "enddate" FROM "Source"."CustomerXML" AS c LEFT JOIN "Source"."NameXML" AS n ON c.Customer_Id = n.Customer_Id LEFT JOIN "Source"."AddressXML" AS a ON c.Customer_Id = a.Customer_Id LEFT JOIN "Source"."ContactInfoXML" AS ci ON c.Customer_Id = ci.Customer_Id LEFT JOIN "Source"."C_PHONE_1_XML" AS p1 ON ci.ContactInfo_Id = p1.ContactInfo_Id LEFT JOIN "Source"."C_PHONE_2_XML" AS p2 ON ci.ContactInfo_Id = p2.ContactInfo_Id LEFT JOIN "Source"."C_PHONE_3_XML" AS p3 ON ci.ContactInfo_Id = p3.ContactInfo_Id LEFT JOIN "Source"."TaxInfoXML" AS t ON c.Customer_Id = t.Customer_Id LEFT JOIN "Source"."TaxRate" AS tr_nat ON t.C_NAT_TX_ID = tr_nat.TX_ID LEFT JOIN "Source"."TaxRate" AS tr_loc ON t.C_LCL_TX_ID = tr_loc.TX_ID LEFT JOIN "Source"."ActionXML" AS act ON c.Action_Id = act.Action_Id);
